aicfb_find_component(struct platform_driver **drv, int id, int len) {
  struct platform_driver **driver = drv;
  int ret, i;

  for (i = 0; i < len; i++) {
    if (driver[i]->component_type == id)
      break;
  }

  if (i >= len || !driver[i] || !driver[i]->probe)
    return NULL;

  ret = driver[i]->probe();
  if (ret)
    return NULL;

  pr_debug("find component: %s\n", driver[i]->name);

  return driver[i];
}

