  hal_gpio_direction_input(g, p);
  hal_gpio_set_bias_pull(g, p, PIN_PULL_UP);
  hal_gpio_set_irq_mode(g, p, PIN_IRQ_MODE_EDGE_FALLING);
  hal_gpio_clr_irq_stat(g, p);

