  up_disable_irq(priv->irq_num);

  /* Start polling mode work queue. */
  ret = gt911_queue_worker(priv,
                           MSEC2TICK(CONFIG_AIC_TOUCH_GT911_POLL_INTERVAL_MS),
                           false);
  if (ret < 0) {
