/********************
 *  SINGLETON CONTEXT
 **********************/

static app_context_t s_app_ctx;

app_context_t *app_ctx_get(void)
{
    return &s_app_ctx;
}

static bool path_exists(const char *path)
{
    return path != NULL && access(path, F_OK) == 0;
}

static bool wait_for_path(const char *path, uint32_t timeout_ms)
{
    uint32_t elapsed = 0;
    const uint32_t poll_ms = 50;

    if (path == NULL || path[0] == '\0') {
        return false;
    }

    for (;;) {
        if (path_exists(path)) {
            return true;
        }

        if (elapsed >= timeout_ms) {
            break;
        }

        uint32_t wait_ms = timeout_ms - elapsed;
        if (wait_ms > poll_ms) {
            wait_ms = poll_ms;
        }

        usleep(wait_ms * 1000);
        elapsed += wait_ms;
    }

    return false;
}

static const char *select_display_path(void)
{
    const char *configured = NULL;

#ifdef CONFIG_APP_LVGL_APP_FB_PATH
    configured = CONFIG_APP_LVGL_APP_FB_PATH;
#endif

#if LV_USE_NUTTX_LCD
    if (configured == NULL || configured[0] == '\0' ||
        strcmp(configured, "/dev/fb0") == 0) {
        return "/dev/lcd0";
    }
#endif

    return configured != NULL && configured[0] != '\0' ? configured : "/dev/fb0";
}

static int try_nuttx_init(const char *fb_path,
                          const char *input_path,
                          lv_nuttx_result_t *result)
{
    lv_nuttx_dsc_t dsc;

    memset(result, 0, sizeof(*result));
    lv_nuttx_dsc_init(&dsc);
    dsc.fb_path = fb_path;
    dsc.input_path = input_path;

    syslog(LOG_INFO,
           "[%s] lv_nuttx_init: fb=%s input=%s LV_COLOR_DEPTH=%d\n",
           LOG_TAG,
           dsc.fb_path ? dsc.fb_path : "(null)",
           dsc.input_path ? dsc.input_path : "(null)",
           LV_COLOR_DEPTH);

    lv_nuttx_init(&dsc, result);

    syslog(LOG_INFO,
           "[%s] lv_nuttx_init result: disp=%p indev=%p utouch=%p mouse=%p\n",
           LOG_TAG, result->disp, result->indev,
           result->utouch_indev, result->mouse_indev);

    return result->disp != NULL ? 0 : -ENODEV;
}

static void log_display_state(lv_display_t *display)
{
    if (display == NULL) {
        syslog(LOG_ERR, "[%s] display handle is NULL\n", LOG_TAG);
        return;
    }

    syslog(LOG_INFO,
           "[%s] display registered: handle=%p default=%p res=%ldx%ld fmt=%d\n",
           LOG_TAG, display, lv_display_get_default(),
           (long)lv_display_get_horizontal_resolution(display),
           (long)lv_display_get_vertical_resolution(display),
           (int)lv_display_get_color_format(display));
}

static void create_boot_diagnostic_screen(void)
{
    lv_obj_t *screen = lv_screen_active();
    lv_obj_t *bar;
    lv_obj_t *label;

    if (screen == NULL) {
        syslog(LOG_ERR, "[%s] active LVGL screen is NULL\n", LOG_TAG);
        return;
    }

    lv_obj_set_style_bg_color(screen, lv_color_hex(0x102030), 0);
    lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);

    bar = lv_obj_create(screen);
    lv_obj_set_size(bar, LV_PCT(100), 14);
    lv_obj_align(bar, LV_ALIGN_TOP_MID, 0, 0);
    lv_obj_set_style_bg_color(bar, lv_color_hex(0xff3344), 0);
    lv_obj_set_style_border_width(bar, 0, 0);
    lv_obj_set_style_radius(bar, 0, 0);

    label = lv_label_create(screen);
    lv_label_set_text(label, "LVGL init OK / 中文显示检查");
    lv_obj_set_style_text_color(label, lv_color_white(), 0);
    lv_obj_center(label);

    lv_timer_handler();
    lv_refr_now(NULL);
    syslog(LOG_INFO, "[%s] boot diagnostic frame requested\n", LOG_TAG);
}


/**********************
 *  IMPLEMENTATION
 **********************/

int app_init(void)
{
    int ret;
    app_context_t *ctx = app_ctx_get();

    syslog(LOG_INFO, "[%s] Starting XFC Smart Panel...\n", LOG_TAG);

    memset(ctx, 0, sizeof(*ctx));
    app_sensor_data_init();

    if (!lv_is_initialized()) {
        syslog(LOG_INFO, "[%s] calling lv_init()\n", LOG_TAG);
        lv_init();
    } else {
        syslog(LOG_WARNING, "[%s] LVGL was already initialized\n", LOG_TAG);
    }

    /* ------------------------------------------------
     * Step 1: Initialize NuttX display & input drivers
     * ------------------------------------------------ */
#if LV_USE_NUTTX
    lv_nuttx_result_t result;
    const char *display_path = select_display_path();
    const char *input_path = NULL;
    const char *fallback_path;
    uint32_t wait_ms = CONFIG_APP_LVGL_APP_DEVICE_WAIT_MS;

#ifdef CONFIG_APP_LVGL_APP_INPUT_PATH
    input_path = CONFIG_APP_LVGL_APP_INPUT_PATH;
#endif

    if (!wait_for_path(display_path, wait_ms)) {
        syslog(LOG_WARNING,
               "[%s] display node %s not ready after %"PRIu32" ms\n",
               LOG_TAG, display_path, wait_ms);
    }

    ret = try_nuttx_init(display_path, input_path, &result);
    if (ret < 0) {
        lv_nuttx_deinit(&result);
        fallback_path = strcmp(display_path, "/dev/fb0") == 0 ?
                        "/dev/lcd0" : "/dev/fb0";
        syslog(LOG_WARNING,
               "[%s] retry display init with fallback %s\n",
               LOG_TAG, fallback_path);
        (void)wait_for_path(fallback_path, wait_ms);
        ret = try_nuttx_init(fallback_path, input_path, &result);
    }

    if (ret < 0 || result.disp == NULL) {
        syslog(LOG_ERR,
               "[%s] LVGL display registration failed, check LCD/fb driver readiness\n",
               LOG_TAG);
        return -ENODEV;
    }

    ctx->display = result.disp;
    ctx->indev = result.indev;
#else
    /* Non-NuttX: assume lv_init() was called and display exists */
    ctx->display = lv_display_get_default();
    ctx->indev = lv_indev_get_next(NULL);
#endif

    ctx->main_screen = lv_screen_active();
    if (ctx->main_screen == NULL) {
        syslog(LOG_ERR, "[%s] failed to get active screen\n", LOG_TAG);
        return -ENODEV;
    }

    log_display_state(ctx->display);
    create_boot_diagnostic_screen();

    /* ------------------------------------------------
     * Step 2: Initialize application state
     * ------------------------------------------------ */
    state_manager_init();
    syslog(LOG_INFO, "[%s] State manager initialized\n", LOG_TAG);

