    };
    pid_t pid;
    int ret;

    (void)argc;
    (void)argv;

    usleep(CONFIG_APP_LVGL_APP_AUTOSTART_DELAY_MS * 1000);

    ret = posix_spawn_file_actions_init(&actions);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] autostart actions init failed: %d\n",
               LOG_TAG, ret);
        return ret;
    }

    ret = posix_spawn_file_actions_addopen(&actions, 0, "/dev/null",
                                           O_RDONLY, 0);
    if (ret == 0) {
        ret = posix_spawn_file_actions_addopen(&actions, 1, "/dev/null",
                                               O_WRONLY, 0);
    }

    if (ret == 0) {
        ret = posix_spawn_file_actions_addopen(&actions, 2, "/dev/null",
                                               O_WRONLY, 0);
    }

    if (ret != 0) {
        syslog(LOG_ERR, "[%s] autostart stdio redirect failed: %d\n",
               LOG_TAG, ret);
        posix_spawn_file_actions_destroy(&actions);
        return ret;
    }

    ret = posix_spawnattr_init(&attr);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] autostart attr init failed: %d\n",
               LOG_TAG, ret);
        posix_spawn_file_actions_destroy(&actions);
        return ret;
    }

    posix_spawnattr_setpriority(&attr, CONFIG_APP_LVGL_APP_PRIORITY);
    posix_spawnattr_setstacksize(&attr, CONFIG_APP_LVGL_APP_STACKSIZE);

    pid = task_spawn("lvgl_app", lvgl_app_main, &actions, &attr,
                     child_argv, NULL);
    if (pid < 0) {
        syslog(LOG_ERR, "[%s] autostart spawn failed: %d\n", LOG_TAG, pid);
    } else {
        syslog(LOG_INFO, "[%s] autostart pid=%d\n", LOG_TAG, pid);
    }

    posix_spawnattr_destroy(&attr);
    posix_spawn_file_actions_destroy(&actions);

    return pid < 0 ? -pid : 0;
}

