/**
 * NuttX main entry point.
 *
 * Stack size and priority are configured via Kconfig (see Kconfig in this
 * directory). LVGL requires at least 8KB stack; 32KB is recommended for
 * FreeType/ThorVG.
 */
int main(int argc, char *argv[])
{
    bool autostart;
    char **demo_argv;
    int demo_argc;
    int ret;

    if (argc > 1 && strcmp(argv[1], "fbtest") == 0) {
        syslog(LOG_INFO, "[%s] start fbtest\n", LOG_TAG);
        return lvgldemo_port_fbtest();
    }

    autostart = argc > 1 && strcmp(argv[1], APP_AUTOSTART_ARG) == 0;
    demo_argv = autostart ? &argv[2] : &argv[1];
    demo_argc = autostart ? argc - 2 : argc - 1;
    lvgldemo_port_set_args(demo_argc, demo_argv);

    syslog(LOG_INFO, "[%s] XFC Smart Panel starting\n", LOG_TAG);

#ifdef NEED_BOARDINIT
    syslog(LOG_INFO, "[%s] boardctl BOARDIOC_INIT\n", LOG_TAG);
    boardctl(BOARDIOC_INIT, 0);
#endif

    /* Initialize the entire GUI application */
    ret = app_init();
    if (ret < 0) {
        syslog(LOG_ERR, "[%s] app_init failed: %d\n", LOG_TAG, ret);
        return ret;
    }

    /* Main event loop - LVGL timer handler drives everything */
    while (1) {
        uint32_t idle_ms = app_run_once();

        if (idle_ms < APP_LOOP_MIN_SLEEP_MS) {
            idle_ms = APP_LOOP_MIN_SLEEP_MS;
        } else if (idle_ms > APP_LOOP_MAX_SLEEP_MS) {
            idle_ms = APP_LOOP_MAX_SLEEP_MS;
        }

        usleep(idle_ms * 1000);
    }

    /* Not reached */
    return 0;
}
