#endif
}

static int lvgl_app_try_nuttx_init(const char *fb_path)
{
  lv_nuttx_dsc_t dsc;

  memset(&g_lvgl_result, 0, sizeof(g_lvgl_result));
  lv_nuttx_dsc_init(&dsc);
  dsc.fb_path = fb_path;

#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
  dsc.input_path = CONFIG_LVGL_APP_HAL_INPUT_DEV_PATH;
#else
  dsc.input_path = NULL;
#endif

  lv_nuttx_init(&dsc, &g_lvgl_result);
  return g_lvgl_result.disp != NULL ? 0 : -ENODEV;
}

static int lvgl_app_init_display(void)
{
  const char *primary;
  const char *fallback;
  int ret;

  if (g_lvgl_ready)
    {
      return 0;
    }

  if (!lv_is_initialized())
    {
      lv_init();
    }

  primary = lvgl_app_primary_fb_path();
  if (!lvgl_app_wait_path(primary, CONFIG_LVGL_APP_HAL_DISPLAY_DEVICE_WAIT_MS))
    {
      syslog(LOG_WARNING, "%s: display node not ready: %s\n",
             LVGL_APP_TAG, primary);
    }

  ret = lvgl_app_try_nuttx_init(primary);
  if (ret < 0)
    {
      lv_nuttx_deinit(&g_lvgl_result);
      memset(&g_lvgl_result, 0, sizeof(g_lvgl_result));

      fallback = strcmp(primary, "/dev/fb0") == 0 ? "/dev/lcd0" : "/dev/fb0";
      (void)lvgl_app_wait_path(
        fallback, CONFIG_LVGL_APP_HAL_DISPLAY_DEVICE_WAIT_MS);
      ret = lvgl_app_try_nuttx_init(fallback);
    }

  if (ret < 0)
    {
      lv_nuttx_deinit(&g_lvgl_result);
      memset(&g_lvgl_result, 0, sizeof(g_lvgl_result));
      syslog(LOG_ERR, "%s: display init failed: %d\n", LVGL_APP_TAG, ret);
      return ret;
    }

  g_lvgl_ready = true;
  return 0;
}

