    idle_ms = lv_timer_handler();
    loop_count++;

    if ((loop_count % 200u) == 0u) {
        syslog(LOG_INFO, "[%s] lv_timer_handler alive idle=%"PRIu32" ms\n",
               LOG_TAG, idle_ms);
    }

    return idle_ms;
}

